CREATE TYPE subscription_tier AS ENUM ('FREE','ANALYST');
CREATE TYPE asset_type AS ENUM ('EMOJI','PHRASE','SLANG','EMOTICON','ACRONYM');
CREATE TYPE order_side AS ENUM ('BUY','SELL','SHORT','COVER');
CREATE TYPE order_status AS ENUM ('PENDING','FILLED','CANCELLED','REJECTED');
CREATE TYPE ledger_type AS ENUM ('INITIAL_GRANT','TRADE_DEBIT','TRADE_CREDIT','TRADING_FEE','BAILOUT','BANKRUPTCY_RESET','ADMIN_ADJUSTMENT','REWARD','INDEX_FEE');
CREATE TABLE users (id uuid PRIMARY KEY, username text UNIQUE NOT NULL, email text UNIQUE NOT NULL, password_hash text, subscription_tier subscription_tier NOT NULL DEFAULT 'FREE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), portfolio_value_minor bigint NOT NULL DEFAULT 0, lifetime_return numeric(18,8) NOT NULL DEFAULT 0, time_weighted_return numeric(18,8) NOT NULL DEFAULT 0, max_drawdown numeric(18,8) NOT NULL DEFAULT 0, bankruptcies integer NOT NULL DEFAULT 0, bailouts_received integer NOT NULL DEFAULT 0, trades_completed integer NOT NULL DEFAULT 0);
CREATE TABLE accounts (id uuid PRIMARY KEY, user_id uuid UNIQUE NOT NULL REFERENCES users(id), current_balance_minor bigint NOT NULL DEFAULT 0 CHECK(current_balance_minor>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_entries (id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id), type ledger_type NOT NULL, amount_minor bigint NOT NULL, reference_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_account_time_idx ON ledger_entries(account_id,created_at DESC);
CREATE TABLE expressions (id text PRIMARY KEY, ticker text UNIQUE NOT NULL, canonical_expression text NOT NULL, asset_type asset_type NOT NULL, unicode text, display_name text NOT NULL, description text NOT NULL, aliases jsonb NOT NULL DEFAULT '[]', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expression_observations (expression_id text REFERENCES expressions(id), timestamp timestamptz NOT NULL, platform text NOT NULL, language text NOT NULL DEFAULT 'und', context_bucket text NOT NULL DEFAULT 'general', usage_count bigint NOT NULL, eligible_document_count bigint NOT NULL, unique_user_estimate bigint, normalized_usage numeric(20,8) NOT NULL, velocity numeric(20,8), acceleration numeric(20,8), breadth numeric(10,8), PRIMARY KEY(expression_id,timestamp,platform,language,context_bucket));
CREATE INDEX observations_time_idx ON expression_observations(timestamp DESC,platform);
CREATE TABLE expression_semantics (expression_id text REFERENCES expressions(id), timestamp timestamptz NOT NULL, label text NOT NULL, probability numeric(10,8) NOT NULL CHECK(probability BETWEEN 0 AND 1), model_version text NOT NULL, PRIMARY KEY(expression_id,timestamp,label,model_version));
CREATE TABLE market_snapshots (expression_id text REFERENCES expressions(id), timestamp timestamptz NOT NULL, expression_index numeric(20,8) NOT NULL, market_price numeric(20,8) NOT NULL, confidence numeric(8,4), PRIMARY KEY(expression_id,timestamp));
CREATE TABLE orders (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), asset_id text NOT NULL REFERENCES expressions(id), side order_side NOT NULL, quantity numeric(20,8) NOT NULL CHECK(quantity>0), price numeric(20,8), status order_status NOT NULL, submitted_at timestamptz NOT NULL, filled_at timestamptz);
CREATE INDEX orders_user_time_idx ON orders(user_id,submitted_at DESC);
CREATE TABLE fills (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), quantity numeric(20,8) NOT NULL, price numeric(20,8) NOT NULL, fee_minor bigint NOT NULL, filled_at timestamptz NOT NULL);
CREATE TABLE positions (user_id uuid REFERENCES users(id), asset_id text REFERENCES expressions(id), quantity numeric(20,8) NOT NULL, average_entry_price numeric(20,8) NOT NULL, realized_pnl_minor bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL, PRIMARY KEY(user_id,asset_id));
CREATE TABLE indexes (id text PRIMARY KEY, ticker text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL, methodology text NOT NULL, weighting text NOT NULL, rebalance_frequency text NOT NULL, creator_id uuid REFERENCES users(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE index_constituents (index_id text REFERENCES indexes(id), effective_at timestamptz NOT NULL, asset_id text REFERENCES expressions(id), weight numeric(12,10) NOT NULL, PRIMARY KEY(index_id,effective_at,asset_id));
CREATE TABLE index_snapshots (index_id text REFERENCES indexes(id), timestamp timestamptz NOT NULL, value numeric(20,8) NOT NULL, PRIMARY KEY(index_id,timestamp));
CREATE TABLE portfolio_snapshots (user_id uuid REFERENCES users(id), timestamp timestamptz NOT NULL, cash_minor bigint NOT NULL, portfolio_value_minor bigint NOT NULL, gross_exposure_minor bigint NOT NULL, net_exposure_minor bigint NOT NULL, PRIMARY KEY(user_id,timestamp));
CREATE TABLE achievements (id text PRIMARY KEY, name text NOT NULL, description text NOT NULL, rule jsonb NOT NULL);
CREATE TABLE user_achievements (user_id uuid REFERENCES users(id), achievement_id text REFERENCES achievements(id), awarded_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(user_id,achievement_id));
CREATE TABLE events (id uuid PRIMARY KEY, title text NOT NULL, category text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz, affected_assets jsonb NOT NULL, synthetic boolean NOT NULL DEFAULT true);
CREATE TABLE backtests (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), name text NOT NULL, strategy jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE backtest_runs (id uuid PRIMARY KEY, backtest_id uuid REFERENCES backtests(id), started_at timestamptz NOT NULL, completed_at timestamptz, config jsonb NOT NULL, results jsonb, status text NOT NULL);
CREATE TABLE research_posts (id uuid PRIMARY KEY, author_id uuid REFERENCES users(id), title text NOT NULL, assets_covered jsonb NOT NULL, summary text NOT NULL, body text NOT NULL, published_at timestamptz, views bigint NOT NULL DEFAULT 0, likes bigint NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
